    def hole(obj):
        cells, top, left = obj['cells'], obj['top'], obj['left']
        oh, ow = obj['height'], obj['width']
        occupied = {(y-top, x-left) for y,x in cells}
        outside = set(); stack = []
        for y in range(oh):
            for x in range(ow):
                if (y in (0,oh-1) or x in (0,ow-1)) and (y,x) not in occupied:
                    outside.add((y,x)); stack.append((y,x))
